SELECT CASE WHEN balance >= 88000 THEN 'PREMIUM' ELSE 'STANDARD' END AS balance_tier, SIZE(COLLECT_SET(account_type)) AS num_account_types, PERCENTILE_APPROX(balance, 0.9) AS balance_p90, AVG(balance) AS avg_balance, COUNT(CASE WHEN status = 'FROZEN' THEN 1 END) AS frozen_count, SUM(balance) AS total_balance, STDDEV_SAMP(balance) AS balance_stddev FROM accounts GROUP BY CASE WHEN balance >= 88000 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY total_balance DESC
